PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?dept WHERE {
  VALUES ?emp { pi:empl-Karen.Brant%40company.org }
  ?emp pv:memberOf ?dept .
} LIMIT 10

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?dept (SAMPLE(COALESCE(?dLbl, ?dName, STR(?dept))) AS ?deptLabel) WHERE {
  pi:empl-Karen.Brant%40company.org pv:memberOf ?dept .
  OPTIONAL { ?dept rdfs:label ?dLbl }
  OPTIONAL { ?dept pv:name ?dName }
}
GROUP BY ?dept
LIMIT 10

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?phone WHERE { pi:empl-Baldwin.Dirksen%40company.org pv:phone ?phone . }

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?manager ?managerLabel ?managerEmail ?managerPhone WHERE {
  BIND(pi:empl-Heinrich.Hoch%40company.org AS ?employee)
  ?employee pv:hasManager ?manager .
  OPTIONAL { ?manager rdfs:label ?lbl0. }
  OPTIONAL { ?manager pv:name ?name0. }
  OPTIONAL { ?manager pv:email ?managerEmail. }
  OPTIONAL { ?manager pv:phone ?managerPhone. }
  BIND(COALESCE(?lbl0, ?name0, STR(?manager)) AS ?managerLabel)
}
LIMIT 10

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?manager (SAMPLE(COALESCE(?mgrLabel, ?mgrName, STR(?manager))) AS ?managerLabel) WHERE {
  pi:empl-Heinrich.Hoch%40company.org pv:hasManager ?manager .
  OPTIONAL { ?manager rdfs:label ?mgrLabel }
  OPTIONAL { ?manager pv:name ?mgrName }
} GROUP BY ?manager

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?empl ?label ?email WHERE {
  ?empl pv:memberOf pi:dept-85880 .
  OPTIONAL { ?empl rdfs:label ?lbl0 }
  OPTIONAL { ?empl pv:name ?name0 }
  OPTIONAL { ?empl pv:email ?email }
  BIND(COALESCE(?lbl0, ?name0, STR(?empl)) AS ?label)
  FILTER(CONTAINS(LCASE(?label), "sabrina"))
} LIMIT 10

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
