  OPTIONAL { ?empl pv:memberOf ?dept . OPTIONAL { ?dept rdfs:label ?deptLabel } }
  OPTIONAL { ?empl pv:email ?email }
}

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?person ?personLabel ?email ?phone WHERE {
  ?person pv:areaOfExpertise pi:prod-cat-Transistor .
  OPTIONAL { ?person rdfs:label ?lbl0. }
  OPTIONAL { ?person pv:name ?name0. }
  BIND(COALESCE(?lbl0,?name0,STR(?person)) AS ?personLabel) .
  OPTIONAL { ?person pv:email ?email. }
  OPTIONAL { ?person pv:phone ?phone. }
}
ORDER BY ?personLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
