PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?emp ?label ?email ?phone WHERE {
  ?emp pv:areaOfExpertise pi:prod-cat-Sensor .
  OPTIONAL { ?emp rdfs:label ?lbl0 . }
  OPTIONAL { ?emp pv:name ?name0 . }
  OPTIONAL { ?emp pv:email ?email . }
  OPTIONAL { ?emp pv:phone ?phone . }
  BIND(COALESCE(?lbl0,?name0,STR(?emp)) AS ?label)
}
ORDER BY ?label

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?mgr (SAMPLE(COALESCE(?ml, ?mname, STR(?mgr))) AS ?mgrLabel) (COUNT(DISTINCT ?emp) AS ?memberCount) WHERE {
  ?emp pv:memberOf pi:dept-41622 .
  ?emp pv:hasManager ?mgr .
  OPTIONAL { ?mgr rdfs:label ?ml }
  OPTIONAL { ?mgr pv:name ?mname }
}
GROUP BY ?mgr
ORDER BY DESC(?memberCount)
LIMIT 1

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?dept ?deptLabel WHERE {
  BIND(pi:hw-M558-2275045 AS ?product)
  {
    ?product pv:hasProductManager ?mgr .
    ?mgr pv:memberOf ?dept .
  }
  UNION
  {
    ?product pv:hasDepartment ?dept .
  }
  UNION
  {
    ?product pv:handledBy ?dept .
  }
  OPTIONAL { ?dept rdfs:label ?deptLabel. }
} LIMIT 10

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?dept ?deptLabel WHERE {
  BIND(pi:hw-M558-2275045 AS ?product)
  OPTIONAL {
    ?product pv:hasProductManager ?mgr .
    ?mgr pv:memberOf ?dept .
  }
  OPTIONAL {
    ?product pv:memberOf ?dept .
  }
  OPTIONAL { ?dept rdfs:label ?deptLabel }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?prod) AS ?count) WHERE {
  ?prod rdf:type ?type .
  FILTER(?type IN (pv:Product, pv:Hardware)) .
  OPTIONAL { ?prod rdfs:label ?lbl }
  OPTIONAL { ?prod pv:name ?name }
  BIND(LCASE(COALESCE(STR(?lbl), STR(?name), "")) AS ?txt)
  FILTER(CONTAINS(?txt, "sensor") && CONTAINS(?txt, "switch"))
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(DISTINCT ?product) AS ?count) WHERE {
  ?product (rdfs:label|pv:name) ?lbl .
  FILTER(regex(?lbl, "sensor[- ]?switch|sensor[- ]?schalter", "i"))
}

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?empl ?emplLabel ?email ?phone ?expert ?expertLabel WHERE {
  ?empl pv:memberOf pi:dept-85880 .
  ?empl pv:areaOfExpertise ?expert .
  OPTIONAL { ?empl pv:email ?email }
  OPTIONAL { ?empl pv:phone ?phone }
  OPTIONAL { ?empl rdfs:label ?empl_lbl0 }
  OPTIONAL { ?empl pv:name ?empl_name0 }
  BIND(COALESCE(?empl_lbl0, ?empl_name0, STR(?empl)) AS ?emplLabel)
  OPTIONAL { ?expert rdfs:label ?expert_lbl0 }
  OPTIONAL { ?expert pv:name ?expert_name0 }
  BIND(COALESCE(?expert_lbl0, ?expert_name0, STR(?expert)) AS ?expertLabel)
  FILTER(CONTAINS(LCASE(?expertLabel), "network"))
}

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?empl (SAMPLE(COALESCE(?lbl0, ?pname0, STR(?empl))) AS ?label) (SAMPLE(?email0) AS ?email) (SAMPLE(?phone0) AS ?phone) WHERE {
  ?empl pv:memberOf pi:dept-85880 .
  ?empl pv:areaOfExpertise pi:prod-cat-Network .
  OPTIONAL { ?empl rdfs:label ?lbl0. }
  OPTIONAL { ?empl pv:name ?pname0. }
  OPTIONAL { ?empl pv:email ?email0. }
  OPTIONAL { ?empl pv:phone ?phone0. }
} GROUP BY ?empl

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?dept (SAMPLE(COALESCE(?lbl0, ?name0, STR(?dept))) AS ?deptLabel) WHERE {
  ?empl pv:areaOfExpertise pi:prod-cat-Transducer ;
        pv:memberOf ?dept .
  OPTIONAL { ?dept rdfs:label ?lbl0 }
  OPTIONAL { ?dept pv:name ?name0 }
} GROUP BY ?dept
ORDER BY ?deptLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?dept (COALESCE(?lbl0, ?name0, STR(?dept)) AS ?deptLabel) WHERE {
  ?emp pv:areaOfExpertise ?expert .
  VALUES ?expert { pi:prod-cat-Sensor pi:prod-cat-Transducer }
  ?emp pv:memberOf ?dept .
  OPTIONAL { ?dept rdfs:label ?lbl0 }
  OPTIONAL { ?dept pv:name ?name0 }
} ORDER BY ?deptLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?supplier (SAMPLE(COALESCE(?lbl0, ?name0, STR(?supplier))) AS ?supplierLabel) WHERE {
  ?product pv:hasCategory pi:prod-cat-Compensator .
  ?product pv:hasSupplier ?supplier .
  OPTIONAL { ?supplier rdfs:label ?lbl0. }
  OPTIONAL { ?supplier pv:name ?name0. }
}
GROUP BY ?supplier
ORDER BY ?supplierLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?supplier ?supplierLabel WHERE {
  ?product pv:hasCategory pi:prod-cat-Compensator .
  ?product pv:hasSupplier ?supplier .
  OPTIONAL { ?supplier rdfs:label ?lbl }
  OPTIONAL { ?supplier pv:name ?name }
  BIND(COALESCE(?lbl, ?name, STR(?supplier)) AS ?supplierLabel)
}
ORDER BY ?supplierLabel

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (COUNT(DISTINCT ?supplier) AS ?count) WHERE {
  ?supplier pv:country <http://dbpedia.org/resource/France> .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (COUNT(DISTINCT ?supplier) AS ?count) WHERE {
  ?product pv:hasSupplier ?supplier .
  ?supplier pv:country <http://dbpedia.org/resource/France> .
}

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?supplier ?supplierLabel ?country ?countryLabel WHERE {
  ?product pv:hasCategory pi:prod-cat-Compensator .
  ?product pv:hasSupplier ?supplier .

  OPTIONAL { ?supplier rdfs:label ?supplierLbl0 }
  OPTIONAL { ?supplier pv:name ?supplierName0 }
  BIND(COALESCE(?supplierLbl0, ?supplierName0, STR(?supplier)) AS ?supplierLabel)

  ?supplier pv:country ?country .
  OPTIONAL { ?country rdfs:label ?countryLbl0 }
  OPTIONAL { ?country pv:name ?countryName0 }
  BIND(COALESCE(?countryLbl0, ?countryName0, STR(?country)) AS ?countryLabel)

  FILTER(
    CONTAINS(LCASE(?countryLabel), "france") ||
    CONTAINS(LCASE(STR(?country)), "france")
  )
} ORDER BY ?supplierLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?product ?productLabel ?amount ?currency ?supplier ?supplierLabel ?country WHERE {
  {
    SELECT (MIN(?amt) AS ?minAmount) WHERE {
      ?p pv:hasCategory pi:prod-cat-Encoder ;
         pv:hasSupplier ?s ;
         pv:price ?ps .
      ?s pv:country ?country .
      FILTER(?country IN (<http://dbpedia.org/resource/France>, <http://dbpedia.org/resource/Germany>)) .
      ?ps pv:amount ?amt ;
          pv:currency "EUR" .
    }
  }
  ?product pv:hasCategory pi:prod-cat-Encoder ;
           pv:hasSupplier ?supplier ;
           pv:price ?priceSpec .
  ?supplier pv:country ?country .
  ?priceSpec pv:amount ?amount ; pv:currency ?currency .
  FILTER(?country IN (<http://dbpedia.org/resource/France>, <http://dbpedia.org/resource/Germany>)) .
  FILTER(?amount = ?minAmount) .
  OPTIONAL { ?product rdfs:label ?plbl }
  OPTIONAL { ?supplier rdfs:label ?slbl }
  BIND(COALESCE(?plbl, ?product) AS ?productLabel)
  BIND(COALESCE(?slbl, ?supplier) AS ?supplierLabel)
}
ORDER BY ?supplierLabel ?productLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?product ?productLabel ?amount ?supplier ?supplierLabel ?countryLabel WHERE {
  ?product pv:hasCategory pi:prod-cat-Encoder .
  ?product pv:hasSupplier ?supplier .
  ?product pv:price ?priceNode .
  ?priceNode pv:amount ?amount .
  ?supplier pv:country ?country .
  FILTER(?country IN (<http://dbpedia.org/resource/France>, <http://dbpedia.org/resource/Germany>))

  {
    SELECT (MIN(?amt) AS ?minAmount) WHERE {
      ?p pv:hasCategory pi:prod-cat-Encoder .
      ?p pv:hasSupplier ?s .
      ?p pv:price ?pr .
      ?pr pv:amount ?amt .
      ?s pv:country ?c .
      FILTER(?c IN (<http://dbpedia.org/resource/France>, <http://dbpedia.org/resource/Germany>))
    }
  }
  ?priceNode pv:amount ?amount .
  FILTER(?amount = ?minAmount)

  OPTIONAL { ?product rdfs:label ?productLabel0 }
  OPTIONAL { ?product pv:name ?productName0 }
  OPTIONAL { ?supplier rdfs:label ?supplierLabel0 }
  OPTIONAL { ?supplier pv:name ?supplierName0 }
  OPTIONAL { ?country rdfs:label ?countryLabel0 }
  BIND(COALESCE(?productLabel0, ?productName0, STR(?product)) AS ?productLabel)
  BIND(COALESCE(?supplierLabel0, ?supplierName0, STR(?supplier)) AS ?supplierLabel)
  BIND(COALESCE(?countryLabel0, STR(?country)) AS ?countryLabel)
}
LIMIT 50

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?supplier (SAMPLE(COALESCE(rdfs:label,pv:name,STR(?supplier))) AS ?supplierLabel) (SAMPLE(?locality) AS ?localitySample) WHERE {
  ?product pv:hasSupplier ?supplier .
  OPTIONAL { ?supplier pv:addressLocality ?locality. }
  OPTIONAL { ?supplier pv:addressText ?addrText. }
  FILTER(
    (BOUND(?locality) && CONTAINS(LCASE(STR(?locality)), "toulouse")) ||
    (BOUND(?addrText) && CONTAINS(LCASE(STR(?addrText)), "toulouse"))
  )
}
GROUP BY ?supplier
LIMIT 100

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?supplier (COALESCE(?lbl0, ?name0, STR(?supplier)) AS ?supplierLabel) WHERE {
  ?supplier pv:addressLocality ?locality .
  FILTER(CONTAINS(LCASE(STR(?locality)), "toulouse"))
  OPTIONAL { ?supplier rdfs:label ?lbl0 }
  OPTIONAL { ?supplier pv:name ?name0 }
} ORDER BY ?supplierLabel

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?supplier (SAMPLE(COALESCE(?lbl0,?name0,STR(?supplier))) AS ?supplierLabel) WHERE {
  ?supplier ?p ?o .
  OPTIONAL { ?supplier rdfs:label ?lbl0 }
  OPTIONAL { ?supplier pv:name ?name0 }
  OPTIONAL { ?supplier pv:addressLocality ?locality }
  OPTIONAL { ?supplier pv:addressText ?addrText }
  BIND(COALESCE(STR(?locality), STR(?addrText), "") AS ?locStr)
  FILTER(CONTAINS(LCASE(?locStr), "toulouse"))
}
GROUP BY ?supplier
ORDER BY ?supplierLabel

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?product ?minPrice ?label WHERE {
  {
    SELECT (MIN(?price) AS ?minPrice) WHERE {
      ?p0 pv:hasCategory pi:prod-cat-Oscillator .
      ?p0 pv:price ?price .
    }
  }
  ?product pv:hasCategory pi:prod-cat-Oscillator ;
           pv:price ?minPrice .
  OPTIONAL { ?product rdfs:label ?lbl0 }
  OPTIONAL { ?product pv:name ?name0 }
  BIND(COALESCE(?lbl0, ?name0, STR(?product)) AS ?label)
}

PREFIX pi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?product ?productLabel ?priceNode ?amount ?currency WHERE {
  {
    SELECT (MIN(?amt) AS ?minAmount) WHERE {
      ?prod pv:hasCategory pi:prod-cat-Oscillator ;
            pv:price ?pr .
      ?pr pv:amount ?amt .
    }
  }
  ?product pv:hasCategory pi:prod-cat-Oscillator ;
           pv:price ?priceNode .
  ?priceNode pv:amount ?amount .
  OPTIONAL { ?priceNode pv:currency ?currency. }
  FILTER(?amount = ?minAmount)
  OPTIONAL { ?product rdfs:label ?lbl0. }
  OPTIONAL { ?product pv:name ?name0. }
  BIND(COALESCE(?lbl0, ?name0, STR(?product)) AS ?productLabel)
}
ORDER BY ?product

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?service (COALESCE(rdfs:label, pv:name, STR(?service)) AS ?label) ?price ?amount ?currency WHERE {
  ?service rdf:type pv:Service .
  ?service pv:price ?price .
  ?price pv:amount ?amount .
  OPTIONAL { ?price pv:currency ?currency }
} ORDER BY DESC(xsd:decimal(?amount)) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?service (SAMPLE(COALESCE(rdfs:label,pv:name,STR(?service))) AS ?label) ?amount ?currency WHERE {
  ?service rdf:type pv:Service .
  ?service pv:price ?priceObj .
  ?priceObj pv:amount ?amount .
  OPTIONAL { ?priceObj pv:currency ?currency }
  OPTIONAL { ?service rdfs:label ?lbl }
  OPTIONAL { ?service pv:name ?name }
  BIND(COALESCE(?lbl,?name,STR(?service)) AS ?label)
  {
    SELECT (MAX(xsd:decimal(?amt)) AS ?maxAmount) WHERE {
      ?s rdf:type pv:Service .
      ?s pv:price ?p .
      ?p pv:amount ?amt .
    }
  }
  FILTER(xsd:decimal(?amount) = ?maxAmount)
} GROUP BY ?service ?amount ?currency

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?mgr ?mgrLabel ?service ?serviceLabel ?amount ?currency WHERE {
  {
    SELECT (MAX(xsd:decimal(?amt)) AS ?maxAmount) WHERE {
      ?svc a pv:Service .
      ?svc pv:price ?pr .
      ?pr pv:amount ?amt .
    }
  }
  ?service a pv:Service ;
           pv:price ?pr2 .
  ?pr2 pv:amount ?amount .
  OPTIONAL { ?pr2 pv:currency ?currency . }
  FILTER(xsd:decimal(?amount) = ?maxAmount)
  OPTIONAL { ?service rdfs:label ?svcLbl . }
  OPTIONAL { ?service pv:name ?svcName . }
  BIND(COALESCE(?svcLbl, ?svcName, STR(?service)) AS ?serviceLabel)
  OPTIONAL { ?service pv:hasProductManager ?mgr . }
  OPTIONAL { ?mgr rdfs:label ?mgrLbl . }
  OPTIONAL { ?mgr pv:name ?mgrName . }
  BIND(COALESCE(?mgrLbl, ?mgrName, STR(?mgr)) AS ?mgrLabel)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?service ?serviceLabel ?mgr ?mgrLabel ?email ?phone ?amt WHERE {
  {
    SELECT ?service ?amt WHERE {
      ?service rdf:type pv:Service .
      ?service pv:price ?priceObj .
      ?priceObj pv:amount ?amt .
    } ORDER BY DESC(?amt) LIMIT 1
  }
  OPTIONAL { ?service rdfs:label ?sLbl }
  OPTIONAL { ?service pv:name ?sName }
  BIND(COALESCE(?sLbl, ?sName, STR(?service)) AS ?serviceLabel)
  OPTIONAL {
    ?service pv:hasProductManager ?mgr .
    OPTIONAL { ?mgr rdfs:label ?mLbl }
    OPTIONAL { ?mgr pv:email ?email }
