PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?product ?id ?name ?width WHERE {
  {
    SELECT (MAX(?wVal) AS ?threshold) WHERE {
      {
        SELECT (COUNT(DISTINCT ?p0) AS ?N) WHERE {
          ?p0 rdf:type pv:Hardware .
          ?p0 pv:width_mm ?w0 .
        }
      }
      {
        SELECT ?wVal (COUNT(DISTINCT ?p_ge) AS ?count_ge) WHERE {
          ?p_val rdf:type pv:Hardware .
          ?p_val pv:width_mm ?wVal .
          ?p_ge rdf:type pv:Hardware .
          ?p_ge pv:width_mm ?w2 .
          FILTER(?w2 >= ?wVal)
        } GROUP BY ?wVal
      }
      BIND(CEIL(?N * 0.1) AS ?K)
      FILTER(?count_ge >= ?K)
    }
  }

  ?product rdf:type pv:Hardware .
  ?product pv:width_mm ?width .
  FILTER(?width >= ?threshold)

  OPTIONAL { ?product pv:id ?id }
  OPTIONAL { ?product pv:name ?name }
  OPTIONAL { ?product rdfs:label ?lbl }
} ORDER BY DESC(?width) ?product

